package com.zerostreams.app;
import android.content.*;import android.graphics.Color;import android.widget.*;import android.view.*;import androidx.test.core.app.ActivityScenario;import androidx.test.platform.app.InstrumentationRegistry;import org.junit.*;import org.json.*;import java.lang.reflect.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
public class AppearanceTest {
 Object field(MainActivity a,String name){try{Field f=MainActivity.class.getDeclaredField(name);f.setAccessible(true);return f.get(a);}catch(Exception e){throw new RuntimeException(e);}}
 @Test public void immediatePersistentThemesAndExactlyTenLogoPresses()throws Exception{Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();SharedPreferences prefs=c.getSharedPreferences("zero",Context.MODE_PRIVATE);String before=prefs.getString("theme","dark");Intent intent=new Intent(c,MainActivity.class).putExtra("downloads",true);try(ActivityScenario<MainActivity> scenario=ActivityScenario.launch(intent)){scenario.onActivity(a->{String[] names={"dark","light","ocean","orchid","sunset"},backgrounds={"#090a10","#f3f5f9","#081b29","#18132b","#101b2d"};for(int i=0;i<names.length;i++){prefs.edit().putString("theme",names[i]).commit();a.switchPalette(names[i]);Assert.assertEquals(Color.parseColor(backgrounds[i]),a.BG);Assert.assertFalse(a.isFinishing());}for(int i=0;i<9;i++)a.easterEgg();Assert.assertFalse((Boolean)field(a,"eggMode"));a.easterEgg();Assert.assertTrue((Boolean)field(a,"eggMode"));a.switchPalette("light");Assert.assertEquals(Color.parseColor("#18132b"),a.BG);Assert.assertEquals("sunset",prefs.getString("theme",""));a.easterEgg();Assert.assertFalse((Boolean)field(a,"eggMode"));Assert.assertEquals(Color.parseColor("#101b2d"),a.BG);});scenario.recreate();scenario.onActivity(a->Assert.assertEquals(Color.parseColor("#101b2d"),a.BG));}finally{prefs.edit().putString("theme",before).commit();}}
 @Test public void delayedInformationArtworkFallbackAndFocusCancellation()throws Exception{Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();SharedPreferences prefs=c.getSharedPreferences("zero",Context.MODE_PRIVATE);boolean info=prefs.getBoolean("focusInfo",true),trailer=prefs.getBoolean("focusTrailer",true);int delay=prefs.getInt("previewDelay",900);prefs.edit().putBoolean("focusInfo",true).putBoolean("focusTrailer",true).putInt("previewDelay",500).commit();CountDownLatch earlyCheck=new CountDownLatch(1);AtomicBoolean earlyClear=new AtomicBoolean();Catalog.Item item=new Catalog.Item(new JSONObject().put("id","tmdb-movie-550").put("title","Fixture Movie").put("type","movie"));try(ActivityScenario<MainActivity> scenario=ActivityScenario.launch(new Intent(c,MainActivity.class).putExtra("downloads",true))){scenario.onActivity(a->{Map<String,JSONObject> metadata=(Map<String,JSONObject>)field(a,"previewMetadata");try{metadata.put(item.id,new JSONObject().put("overview","Fixture information").put("runtime",120).put("genres",new JSONArray()));}catch(Exception e){throw new RuntimeException(e);}LinearLayout content=(LinearLayout)field(a,"content");View card=a.card(item,1);content.addView(card);a.focusPreview(item,card);Assert.assertNull(field(a,"previewPopup"));new android.os.Handler(android.os.Looper.getMainLooper()).postDelayed(()->{earlyClear.set(field(a,"previewPopup")==null);earlyCheck.countDown();},250);});Assert.assertTrue(earlyCheck.await(5,TimeUnit.SECONDS));Assert.assertTrue("Preview remains hidden before its focus delay",earlyClear.get());Thread.sleep(650);scenario.onActivity(a->{Assert.assertNotNull(field(a,"previewPopup"));Assert.assertNull("No trailer retains artwork and information",field(a,"previewWeb"));a.stopPreview();Assert.assertNull(field(a,"previewPopup"));Assert.assertNull(field(a,"previewWeb"));prefs.edit().putBoolean("focusInfo",false).putBoolean("focusTrailer",false).commit();a.focusPreview(item,a.getWindow().getDecorView());});Thread.sleep(650);scenario.onActivity(a->Assert.assertNull(field(a,"previewPopup")));}finally{prefs.edit().putBoolean("focusInfo",info).putBoolean("focusTrailer",trailer).putInt("previewDelay",delay).commit();}}
}
